//! Hardcoded 8×16 bitmap font for terminal rendering.
//!
//! Covers printable ASCII (0x20–0x7E, 95 characters). Each glyph is
//! 16 rows of 8 pixels, stored as one byte per row (MSB = leftmost
//! pixel). The data is the standard IBM VGA/BIOS ROM font, public domain.
//!
//! # Atlas layout
//!
//! `build_atlas` packs all 95 glyphs into a single row:
//! `[16, 760]` I32 tensor (height=16, width=95×8=760).
//! Glyph for character `ch` starts at atlas column `(ch - 0x20) * 8`.

/// Glyph width in pixels.
pub const GLYPH_W: u16 = 8;
/// Glyph height in pixels.
pub const GLYPH_H: u16 = 16;

/// Number of printable ASCII characters (0x20..=0x7E).
const NUM_CHARS: usize = 95;

/// First printable ASCII codepoint.
const FIRST_CHAR: u8 = 0x20;

/// Atlas width in pixels.
pub const ATLAS_W: usize = NUM_CHARS * GLYPH_W as usize; // 760
/// Atlas height in pixels.
pub const ATLAS_H: usize = GLYPH_H as usize; // 16

/// Return the atlas X coordinate for a given ASCII byte.
/// Returns 0 (space) for non-printable characters.
#[inline]
pub fn atlas_x(ch: u8) -> u16 {
    if (0x20..=0x7E).contains(&ch) {
        ((ch - FIRST_CHAR) as u16) * GLYPH_W
    } else {
        0 // map to space
    }
}

/// Build the glyph atlas as a premultiplied-white `[ATLAS_H, ATLAS_W]`
/// I32 buffer. Each "on" pixel is `0xFFFFFFFF`, each "off" pixel is
/// transparent. The graph compositor reads the same alpha byte as coverage.
///
/// The caller uploads this buffer to a backend tensor.
pub fn build_atlas_pixels() -> [u32; ATLAS_W * ATLAS_H] {
    let mut buf = [0u32; ATLAS_W * ATLAS_H];
    for (ci, glyph) in FONT_8X16.chunks_exact(16).enumerate() {
        let base_x = ci * GLYPH_W as usize;
        for (row, &bits) in glyph.iter().enumerate() {
            for col in 0..8 {
                if bits & (0x80 >> col) != 0 {
                    buf[row * ATLAS_W + base_x + col] = 0xFFFF_FFFF;
                }
            }
        }
    }
    buf
}

